    function etf(n) {

    let result = n;

    // Consider all prime factors of n 
    // and subtract their multiples 
    // from result
    for (let p = 2; p * p <= n; ++p) {
        if (n % p === 0) {

            while (n % p === 0)
                n = Math.floor(n / p);

            result -= Math.floor(result / p);
        }
    }

    // If n has a prime factor greater than sqrt(n)
    // (There can be at-most one such prime factor)
    if (n > 1)
        result -= Math.floor(result / n);

    return result;
